    "id": "US20200177193A1",
    "skim": "Voltage controlled oscillator based on complementary current-injection field-effect transistor devices",
    "title": "Voltage controlled oscillator based on complementary current-injection field-effect transistor devices",
    "holder": "Circuit Seed LLC",
    "year": 2019,
    "status": "abandoned",
